var t=`0398-bangers-and-mash`;var n=`world-0398`;var o=`GB`;var a=`northern-europe`;var s=4;var r=57;var l={en:`Bangers and Mash`,ua:`Сосиски з пюре`};var d={en:`A traditional United Kingdom dish made with potato, fresh pork sausage, whole cow milk, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Велика Британія. Основні інгредієнти: картопля, сира свиняча ковбаса, цільне коров'яче молоко, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`potato`,900,`g`],[`water`,1200,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`fresh-pork-sausage`,700,`g`],[`extra-virgin-olive-oil`,40,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`unsalted-butter`,95,`g`],[`whole-cow-milk`,200,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,300,`g`],[`beef-stock`,260,`ml`],[`all-purpose-flour`,25,`g`]]}];var m={slug:t,id:n,country:`GB`,region:a,servings:4,minutes:57,title:l,text:d,steps:u};export{o as country,m as default,n as id,r as minutes,a as region,s as servings,t as slug,u as steps,d as text,l as title};